package com.hbm.client.reactor.rbmk.failure;
import com.hbm.client.bomb.nuclear.MukeRenderTypes;
import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.Camera;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.client.particle.*;import net.minecraft.client.renderer.GameRenderer;import net.minecraft.client.renderer.texture.TextureManager;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;import org.joml.Vector3f;
/** Original ParticleDigammaSmoke: half-size5 red terrain sprite,100..139life,alpha-before-age and .99 motion. */
final class RbmkDigammaSmoke extends Particle {
 private static final ParticleRenderType TYPE=MukeRenderTypes.cloudTexture(ResourceLocation.parse("hbm:textures/block/particle/particle_base.png"),false);
 RbmkDigammaSmoke(ClientLevel world,double x,double y,double z,double mx,double mz){super(world,x,y,z);lifetime=100+random.nextInt(40);hasPhysics=false;rCol=.5F+random.nextFloat()*.2F;gCol=bCol=0;xd=mx;yd=0;zd=mz;}@Override public void tick(){xo=x;yo=y;zo=z;alpha=1-(float)age/lifetime;if(++age==lifetime)remove();xd*=.99;yd*=.99;zd*=.99;setPos(x+xd,y+yd,z+zd);}@Override public ParticleRenderType getRenderType(){return MukeRenderTypes.ORDERED;}@Override public void render(VertexConsumer out,Camera camera,float partial){if(MukeRenderTypes.defer(this,partial))return;out=MukeRenderTypes.begin(TYPE);var eye=camera.getPosition();float px=(float)(Mth.lerp(partial,xo,x)-eye.x),py=(float)(Mth.lerp(partial,yo,y)-eye.y),pz=(float)(Mth.lerp(partial,zo,z)-eye.z);float[] us={1,1,0,0},vs={1,0,0,1};float[][] corners={{-5,-5,0},{-5,5,0},{5,5,0},{5,-5,0}};for(int i=0;i<4;i++){var point=new Vector3f(corners[i]).rotate(camera.rotation()).add(px,py,pz);out.addVertex(point.x,point.y,point.z).setUv(us[i],vs[i]).setColor(rCol,gCol,bCol,alpha).setLight(240);}}
}
